use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let mut chars = s.chars().peekable();
        if let Some(c) = chars.next() {
            if c.is_alphabetic() {
                let mut result = String::new();
                chars.filter(|c| c.is_alphanumeric() || c == '_').for_each(|c| result.push(c));
                Value::String(result)
            } else {
                Value::Bool(false)
            }
        } else {
            Value::Bool(false)
        }
    } else {
        Value::Bool(false)
    }
}
